    return a+a[:k]"},{"nl":"Recolor all nonzeros to 2 and append the top half when height is 6, or append the first row when height is 3.","code":"def transform(grid):
    a=[[0 if x==0 else 2 for x in r] for r in grid]
    return a+a[:len(grid)//2]"},{"nl":"Convert every nonzero to 2 and extend vertically by one half-period: for the 6-row case use a 3-row prefix; for the 3-row case use a 1-row prefix.","code":"def transform(grid):
    a=[[2 if v else 0 for v in row] for row in grid]
    n=len(a); extra=3 if n==6 else 1
    return a+a[:extra]"},{"nl":"Output the recolored input followed by its first min(3, floor(height/2)) rows.","code":"def transform(grid):
    a=[[2 if v!=0 else 0 for v in row] for row in grid]
    return a+a[:min(3,len(grid)//2)]"},{"nl":"Treat 0 as background and all other colors as foreground 2; append a prefix whose length is the number of columns divided by two.","code":"def transform(grid):
    a=[[2 if v!=0 else 0 for v in row] for row in grid]
    return a+a[:len(grid[0])//2]"},{"nl":"Recolor nonzero cells to 2 and append the first rows until adding half the smaller grid dimension (3 for 6x3, 1 for 3x6).","code":"def transform(grid):
    a=[[2 if v else 0 for v in r] for r in grid]
    extra=min(len(grid)//2, len(grid[0])//2)
    return a+a[:extra]"},{"nl":"Replace all colored cells by 2, then append the first three rows for a tall narrow input and the first row for a short wide input.","code":"def transform(grid):
    a=[[2 if x!=0 else 0 for x in r] for r in grid]
    extra=3 if len(grid)>len(grid[0]) else 1
    return a+a[:extra]"},{"nl":"Normalize colors to 0/2 and append the prefix of length equal to the absolute difference between height and width.","code":"def transform(grid):
    a=[[2 if x!=0 else 0 for x in r] for r in grid]
    return a+a[:abs(len(grid)-len(grid[0]))]"},{"nl":"Change every nonzero to 2 and repeat the top row block, with block size equal to the count of rows in the shorter side divided by one (3 for the 6x3 case, 1 for 3x6).","code":"def transform(grid):
